/* Vigia Rural — protótipo acadêmico portátil, sem dependências externas. */
(() => {
  'use strict';
  const M=window.VRModel,KEY='vigia-rural-demo-v1',SESSION='vigia-rural-session';
  let s,session=null,page='dashboard',selected='TR-001',filters={},modalFocus=null,slideIndex=0,timer=null,toastTimer=null,storageWarning=false;
  try{s=JSON.parse(localStorage.getItem(KEY));if(!s||s.version!==1||!Array.isArray(s.assets))s=M.seed();}catch{s=M.seed();storageWarning=true;}
  try{session=JSON.parse(sessionStorage.getItem(SESSION));}catch{}
  const $=id=>document.getElementById(id);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const isManager=()=>session?.role==='Gestor';
  const opName=id=>s.operators.find(o=>o.id===id)?.name||'Não identificado';
  const areaName=id=>s.areas.find(z=>z.id===id)?.name||'Fora da propriedade';
  const initials=name=>name.split(' ').slice(0,2).map(n=>n[0]).join('');
  const visibleAssets=()=>isManager()?s.assets:s.assets.filter(a=>s.operators.find(o=>o.id===session?.operator)?.assets.includes(a.id));
  const canView=id=>visibleAssets().some(a=>a.id===id);
  const visibleAlerts=()=>s.alerts.filter(a=>canView(a.asset));
  const visibleAudit=()=>s.audit.filter(e=>isManager()||(canView(e.asset)&&(!e.operator||e.operator===session.operator)));
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));}catch{storageWarning=true;toast('O navegador não permitiu salvar. Mantenha esta aba aberta durante a demonstração.');}};
  const paths={shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z M8 12l3 3 5-6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',tractor:'M3 12h11V5h5v10 M8 12V8h6 M4 9h4 M20 15h2 M8 18a3 3 0 1 0-6 0 3 3 0 0 0 6 0 M21 18a4 4 0 1 0-8 0 4 4 0 0 0 8 0',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3c0-4 14-4 14 0v3 M17 4a4 4 0 0 1 0 7 M19 15c3 0 3 3 3 6',bell:'M5 16h14l-2-3V9a5 5 0 0 0-10 0v4z M10 20h4 M12 2v2',folder:'M3 7V4h7l2 3h9v13H3z',check:'m4 12 5 5L20 6',clock:'M12 8v5l4 2 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 4-2 2v3l-3 2-1 3H9l-1-3-3-2v-3l-2-2 2-4 3-1z',signal:'M4 18v3 M9 13v8 M14 8v13 M19 3v18',play:'m8 4 13 8-13 8z',arrow:'M4 12h16 m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',plus:'M12 4v16 M4 12h16',search:'M17 10a7 7 0 1 0-14 0 7 7 0 0 0 14 0 m-2 5 7 7',exit:'M9 3H3v18h6 M9 12h12 m-5-5 5 5-5 5',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',rfid:'M3 5h18v14H3z M7 9h3v5H7z M14 8c4 3 4 5 0 8 M13 11c1 1 1 1 0 2',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0 M15 9a3 3 0 1 0-6 0 3 3 0 0 0 6 0',battery:'M2 7h18v10H2z M22 10v4 M5 10h10v4H5z',pause:'M8 4v16 M16 4v16',refresh:'M20 8a8 8 0 1 0 0 9 M20 3v5h-5',printer:'M6 8V3h12v5 M6 16H3V8h18v8h-3 M6 13h12v8H6z',close:'m5 5 14 14 M19 5 5 19',menu:'M3 6h18 M3 12h18 M3 18h18',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',leaf:'M20 3c-12 0-18 5-15 12s15 6 15-12 M3 21 15 9'};
  const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`;
  const brand=()=>`<div class="brand"><span class="brand-mark">${icon('shield',25)}</span><div>Vigia Rural<small>SEGURANÇA NO CAMPO</small></div></div>`;
  const badge=(text,color)=>`<span class="badge ${color||({'Alerta':'red','Irregular':'red','Crítica':'red','Alta':'red','Atenção':'orange','Média':'orange','Pendente':'orange','Parado':'orange','Offline':'gray','Suspenso':'gray','Encerrada':'gray','Negada':'red','LoRaWAN':'navy'}[text]||'')}">${esc(text)}</span>`;
  const button=(text,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
  const head=(title,description,actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`;
  function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
  function nav(target){page=target;filters={};closeModal();history.replaceState(null,'','#'+target);render();window.scrollTo(0,0);}
  function checkedManager(){if(!isManager())throw Error('Esta ação está disponível somente ao gestor.');}
  function getAsset(id){if(!canView(id))throw Error('Ativo indisponível para este perfil.');return M.asset(s,id);}
  function render(){
    const focus=document.activeElement?.id,caret=document.activeElement?.selectionStart;
    if(!session){$('app').innerHTML=login();return;}
    const allowed=isManager()?['dashboard','mapa','ativos','detalhe','operadores','alertas','ocorrencias','dossie','autorizacoes','areas','historico','configuracoes']:['dashboard','mapa','ativos','detalhe','historico','configuracoes'];
    if(!allowed.includes(page))page='dashboard';
    if(!canView(selected))selected=visibleAssets()[0]?.id;
    const navItems=[['dashboard','grid','Visão geral'],['mapa','map','Monitoramento'],['ativos','tractor','Ativos'],['operadores','users','Operadores'],['alertas','bell','Alertas'],['ocorrencias','folder','Ocorrências'],['autorizacoes','check','Autorizações'],['areas','pin','Áreas permitidas'],['historico','clock','Histórico e auditoria'],['configuracoes','settings','Configurações']];
    const count=visibleAlerts().filter(a=>a.status!=='Resolvido').length;
    const content={dashboard:dashboard,mapa:monitor,ativos:assetsPage,detalhe:assetDetail,operadores:operatorsPage,alertas:alertsPage,ocorrencias:occurrencesPage,dossie:dossier,autorizacoes:requestsPage,areas:areasPage,historico:historyPage,configuracoes:settingsPage}[page]();
    $('app').innerHTML=`<aside class="sidebar" id="sidebar">${brand()}<div class="nav-label">CENTRAL DE OPERAÇÕES</div><nav aria-label="Navegação principal">${navItems.filter(([id])=>allowed.includes(id)).map(([id,ic,label],i)=>`${id==='autorizacoes'?'<div class="nav-label">CONTROLE E GOVERNANÇA</div>':''}<button class="nav-btn ${(page===id||page==='detalhe'&&id==='ativos'||page==='dossie'&&id==='ocorrencias')?'active':''}" data-nav="${id}" ${page===id?'aria-current="page"':''}>${icon(ic,17)}${label}${id==='alertas'&&count?`<span class="count">${count}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="live"><i class="dot"></i> Ambiente de demonstração</div><div class="user"><span class="avatar">${initials(session.name)}</span><div><b>${esc(session.name)}</b><small>${session.role} · Acesso demonstrativo</small></div><button data-action="logout" aria-label="Sair da conta" title="Sair">${icon('exit',17)}</button></div></div></aside><div class="main"><header class="topbar"><div class="farm"><button class="menu-mobile" data-action="menu" aria-label="Abrir navegação">${icon('menu')}</button>${icon('leaf',17)}${esc(s.settings.farm)}<small>Central de segurança</small></div><div class="top-actions"><span class="demo-label">PROTÓTIPO ACADÊMICO</span><small>30 set 2026 · <span id="clock">${s.clock.slice(0,5)}</span></small>${button(icon('play',14)+' Apresentação','presentation','','small')}</div></header><main class="content" id="main-content">${storageWarning?'<div class="notice red" style="margin-bottom:15px">Persistência indisponível neste navegador. Os dados serão mantidos apenas nesta aba.</div>':''}${scenarioBanner()}${content}<footer class="footer"><span>Vigia Rural · Segurança, rastreamento e inteligência operacional</span><span>Dados fictícios · GPS, RFID e comunicação simulados · Sem conexão com hardware</span></footer></main></div>`;
    try{sessionStorage.setItem(KEY+'-view',JSON.stringify({selected,dossierId}));}catch{}
    if(focus&&$(focus)){ $(focus).focus();if(typeof caret==='number'&&$(focus).setSelectionRange)try{$(focus).setSelectionRange(caret,caret);}catch{} }
  }
  function login(){return `<div class="login"><section class="login-visual">${brand()}<div class="intro"><span class="eyebrow">CENTRAL DE GESTÃO DE RISCO</span><h1>O campo conectado.<br>O patrimônio<br>protegido.</h1><p>Saiba onde sua máquina está, quem está operando e se o uso foi autorizado. Tudo em um único lugar.</p><div class="callout" style="color:#b8cdac;border-color:#7fa568;margin-top:32px">Um alerta sem contexto não resolve o problema.</div></div><div class="login-bottom"><span>Rastreamento</span><span>Identificação RFID</span><span>Resposta a ocorrências</span></div><div class="login-art"></div></section><section class="login-form"><div class="login-box"><span class="eyebrow muted">ACESSO À PLATAFORMA</span><h2>Bem-vindo ao Vigia Rural</h2><p>Acompanhe seus ativos e tome decisões com contexto.</p><div class="login-switch"><button class="selected" data-action="login-profile" data-role="Gestor">Gestor</button><button data-action="login-profile" data-role="Operador">Operador</button></div><form id="login-form"><input type="hidden" id="login-role" value="Gestor"><div class="field"><label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="username" value="admin@vigiarural.com" required></div><div class="field"><label for="password">Senha</label><input id="password" name="password" type="password" autocomplete="off" value="admin123" required></div><div id="login-error" class="error" role="alert"></div><button class="btn primary" type="submit">Acessar a central ${icon('arrow',17)}</button></form><div class="login-credentials"><b>Contas de demonstração</b><br>Gestor: admin@vigiarural.com · admin123<br>Operador: operador@vigiarural.com · operador123<br><span>O perfil de operador mostra apenas os ativos vinculados.</span></div>${button('Conheça o projeto '+icon('arrow',14),'presentation','','link')}<p style="font-size:10px;color:#8a9782;margin-top:20px;line-height:1.7">Protótipo acadêmico. Dados fictícios e autenticação demonstrativa. Funciona sem internet.</p></div></section></div>`;}
  function stats(){const list=visibleAssets(),alerts=visibleAlerts().filter(a=>a.status!=='Resolvido');const data=[['Ativos monitorados',list.length,'tractor','Frota da propriedade',''],['Em operação',list.filter(a=>a.status==='Operando').length,'play','Uso em andamento',''],['Parados',list.filter(a=>a.status==='Parado').length,'pause','Ignição desligada',''],['Offline',list.filter(a=>a.connection==='Offline').length,'signal','Última posição conhecida','warn'],['Alertas ativos',alerts.length,'bell','Aguardam acompanhamento','warn'],['Ocorrências críticas',s.occurrences.filter(o=>canView(o.asset)&&o.priority==='Crítica'&&o.status==='Aberta').length,'shield','Prioridade de resposta','critical']];return `<div class="summary">${data.map(([label,n,ic,note,cl])=>`<div class="stat ${cl}"><div class="stat-top">${label}${icon(ic,16)}</div><strong>${n.toString().padStart(2,'0')}</strong><small>${note}</small></div>`).join('')}</div>`;}
  function farmMap(full=false){
    const list=visibleAssets();
    const zones=s.areas.map(z=>`<g><rect x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" rx="1" fill="${z.color}" stroke="#8da37c" stroke-width=".25" stroke-dasharray="1 .6"/><rect x="${z.x+.4}" y="${z.y+.4}" width="${z.w-.8}" height="${z.h-.8}" fill="url(#crop)" opacity=".5"/><text x="${z.x+z.w/2}" y="${z.y+z.h/2}" text-anchor="middle" fill="#667451" font-size="2" letter-spacing=".3">${esc(z.name.toUpperCase())}</text></g>`).join('');
    const route=s.scenario?.asset?M.asset(s,s.scenario.asset).route:[];
    return `<div class="map ${full?'map-board':''}"><div class="map-label">${icon('pin',12)} ${esc(s.settings.farm)} <span class="muted">· mapa esquemático</span></div>${full?'<div class="map-toolbar">'+button(icon('eye',14)+' Ver frota','map-select','','small')+'</div>':''}<svg class="map-art" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Mapa esquemático da propriedade e das áreas permitidas"><defs><pattern id="crop" width="2" height="2" patternUnits="userSpaceOnUse" patternTransform="rotate(18)"><path d="M0 0v2" stroke="#6f8447" stroke-width=".15"/></pattern><pattern id="ground" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M1 1h.1 M5 4h.1" stroke="#7d9465" stroke-width=".2"/></pattern></defs><rect width="100" height="100" fill="#e8ecd8"/><rect width="100" height="100" fill="url(#ground)"/><path d="M-2 84 Q14 95 24 82 T47 88 T74 89 T104 81" fill="none" stroke="#bad4ca" stroke-width="3"/><path d="M5 10 Q-1 25 4 51 T9 88 M1 2 25 8 37 1 M98 1 89 6 96 16" stroke="#c5d6ae" stroke-width="8" fill="none"/>${zones}<path d="M0 54 38 53 83 49 100 42 M38 0 38 100" fill="none" stroke="#f9f7ea" stroke-width="2.8"/><path d="M0 54 38 53 83 49 100 42 M38 0 38 100" fill="none" stroke="#c9b79a" stroke-width=".25" stroke-dasharray="1 1"/><path d="M8 10H87V48H98V89H8Z" fill="none" stroke="#7c9664" stroke-width=".35" stroke-dasharray="1.2 .7"/><rect x="16" y="29" width="10" height="5" fill="#f6f3e7" stroke="#b4b09b" stroke-width=".25"/><path d="m15 29 6-4 6 4" fill="#aaad97"/><rect x="12" y="68" width="8" height="5" fill="#f5efdf" stroke="#b9a585" stroke-width=".3"/>${route.length?`<polyline points="${route.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#be5740" stroke-width=".65" stroke-dasharray="1 .6"/>`:''}<text x="66" y="95" fill="#8a9681" font-size="1.6" letter-spacing=".4">ESTRADA RURAL VR-02</text><text x="93" y="9" fill="#6e8067" font-size="2.5">N ↑</text></svg>${list.map(a=>`<button class="pin ${a.status==='Alerta'?'alert':a.connection==='Offline'?'offline':a.status==='Parado'?'parked':''} ${a.id===selected&&full?'selected':''}" style="left:${a.x}%;top:${a.y}%" data-action="map-asset" data-id="${a.id}" aria-label="${a.id} ${esc(a.name)}: ${a.status}">${icon(a.type==='Veículo de apoio'?'pin':'tractor',15)}${full?`<span class="pin-caption">${a.id}</span>`:''}</button>`).join('')}<div class="map-note">Representação fictícia · sem coordenadas reais</div></div>`;
  }
  const legend=()=>`<div class="map-legend"><span><i class="dot" style="background:#397953"></i>Em operação</span><span><i class="dot" style="background:#987a43"></i>Parado</span><span><i class="dot" style="background:#bb4939"></i>Alerta</span><span><i class="dot" style="background:#8e9389"></i>Offline</span><span style="margin-left:auto">GPS simulado</span></div>`;
  function alertItem(al){return `<div class="alert-item"><div class="alert-icon" ${al.priority==='Média'?'style="background:#f8f0df;color:#aa7b31"':''}>${icon(al.priority==='Crítica'?'shield':'alert',17)}</div><div class="alert-copy"><h3>${esc(al.title)}</h3><p>${al.asset} · ${esc(opName(al.operator))}<br>${esc(al.reason)}</p><div class="meta">${badge(al.priority)}<span>${al.time.slice(0,5)}</span>${button('Analisar '+icon('chevron',11),'alert-detail',`data-id="${al.id}"`,'link small')}</div></div></div>`;}
  function assetTable(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Ativo</th><th>Operador</th><th>Status</th>${compact?'':'<th>Conexão</th><th>Bateria</th><th>Localização</th>'}<th></th></tr></thead><tbody>${list.map(a=>`<tr><td><div class="asset-name"><span class="machine-icon">${icon('tractor',19)}</span><div><button class="row-link" data-action="asset-detail" data-id="${a.id}">${a.id}</button><span class="sub">${esc(a.name)}</span></div></div></td><td>${esc(a.operator?opName(a.operator):'—')}<span class="sub">${a.operator?'RFID identificado':'Sem operador em atividade'}</span></td><td>${badge(a.status)}</td>${compact?'':`<td>${badge(a.connection)}<span class="sub">${a.updated}</span></td><td>${a.battery}%</td><td>${esc(areaName(a.area))}</td>`}<td><button class="icon-btn" data-action="asset-detail" data-id="${a.id}" aria-label="Detalhes de ${a.id}">${icon('chevron',15)}</button></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">Nenhum ativo corresponde aos filtros.</div>':''}</div>`;}
  function dashboard(){const list=visibleAssets(),active=visibleAlerts().filter(a=>a.status!=='Resolvido'),online=list.filter(a=>a.connection!=='Offline').length;return head('Visão geral','Segurança da propriedade, com contexto para cada decisão.',isManager()?button(icon('rfid',15)+' Simular RFID','rfid')+button(icon('play',15)+' Simular incidente','simulate','','primary'):'')+stats()+`<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>Monitoramento da propriedade</h2><p>${list.length} ativos · ${s.areas.length} áreas cadastradas</p></div>${button('Abrir mapa '+icon('arrow',13),'open-map','','link small')}</div>${farmMap()}${legend()}</section><section class="panel"><div class="panel-head"><div><h2>Central de alertas</h2><p>${active.length} alertas aguardam acompanhamento</p></div>${badge('Ao vivo','gray')}</div>${active.slice(0,3).map(alertItem).join('')||'<div class="empty">Nenhum alerta ativo.<br>As atividades normais continuam no histórico.</div>'}${isManager()?'<div style="padding:10px 20px 15px">'+button('Ver todos os alertas '+icon('arrow',13),'open-alerts','','link small')+'</div>':''}</section></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Ativos em destaque</h2><p>Identificação, operação e situação atual</p></div>${button('Ver frota '+icon('arrow',13),'open-assets','','link small')}</div>${assetTable(list.slice(0,4),true)}</section><section class="panel"><div class="panel-head"><div><h2>Conectividade e proteção</h2><p>Disponibilidade na propriedade</p></div>${icon('signal',17)}</div><div class="panel-body"><div class="connection-row"><span>${icon('signal',15)}Rede celular</span><b>${list.filter(a=>a.connection==='Celular').length} ativos</b></div><div class="connection-row"><span>${icon('map',15)}LoRaWAN local</span><b>${list.filter(a=>a.connection==='LoRaWAN').length} ativos</b></div><div class="connection-row"><span>${icon('alert',15)}Sem comunicação</span><b>${list.length-online} ativo(s)</b></div><small>Ativos comunicando</small><div class="bar"><i style="width:${online/list.length*100}%"></i></div><div class="notice">${icon('shield',14)} A contingência LoRaWAN usa um gateway local simulado. Sem ambos os enlaces, exibimos a última posição conhecida.</div><div style="margin-top:16px"><small>Última autorização</small><p style="font-size:11px;line-height:1.8;margin-top:5px">${s.requests.length?esc(s.requests[0].asset+' · '+s.requests[0].status):'12:18 · Ana Souza autorizou exceção no TR-002'}</p></div></div></section></div>`;}
  function monitor(){const a=getAsset(selected);return head('Monitoramento','Localização, identidade e comunicação dos ativos em um só lugar.',isManager()?button(icon('play',15)+' Simular incidente','simulate','','primary'):'')+`<div class="monitor-grid"><section class="panel">${farmMap(true)}${legend()}</section><section class="panel map-info"><span class="eyebrow muted">ATIVO SELECIONADO</span><h2>${a.id}</h2><p class="muted" style="font-size:12px;margin-bottom:14px">${esc(a.name)}</p>${badge(a.status)} ${badge(a.risk)}<div class="data-grid">${datum('Operador',opName(a.operator))}${datum('Velocidade',a.connection==='Offline'?'Sem dado atual':a.speed+' km/h')}${datum('Conexão',a.connection)}${datum('Atualização',a.updated)}${datum('Área',areaName(a.area))}${datum('Geofence',a.allowedAreas.includes(a.area)?'Dentro da área':'Fora da área')}${datum('Ignição',a.ignition?'Ligada':'Desligada')}${datum('Bateria',a.battery+'%')}</div>${a.connection==='Offline'?'<div class="notice red">Última posição conhecida. Comunicação perdida há '+offlineMinutes(a)+' minutos no relógio da simulação.</div>':a.connection==='LoRaWAN'?'<div class="notice">Comunicação de contingência ativa. Celular indisponível · LoRaWAN local ativo.</div>':'<div class="notice">Comunicação principal ativa via rede celular simulada.</div>'}<div style="margin-top:20px">${button('Detalhes do ativo '+icon('arrow',14),'asset-detail',`data-id="${a.id}"`,'primary')}</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Frota monitorada</h2></div>${assetTable(visibleAssets(),true)}</section>`;}
  function offlineMinutes(a){const seconds=t=>t.split(':').reduce((sum,v,i)=>sum+Number(v)*[3600,60,1][i],0);return Math.max(0,Math.floor((seconds(s.clock)-seconds(a.updated))/60));}
  const datum=(label,value)=>`<div class="datum"><span>${esc(label)}</span><b>${esc(value)}</b></div>`;
  function filterField(id,label,opts,value=''){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" data-filter="${id}">${opts.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`;}).join('')}</select></div>`;}
  function assetsPage(){const list=visibleAssets().filter(a=>(!filters.search||(a.id+' '+a.name+' '+opName(a.operator)).toLowerCase().includes(filters.search.toLowerCase()))&&(!filters.status||a.status===filters.status)&&(!filters.type||a.type===filters.type));return head('Ativos','Máquinas agrícolas e veículos de apoio vinculados à propriedade.',button(icon('download',15)+' Exportar frota','export-assets'))+`<div class="filters"><div class="field filter-search"><label for="search">Buscar ativo ou operador</label><input id="search" data-filter="search" value="${esc(filters.search||'')}" placeholder="Código, modelo ou operador"></div>${filterField('status','Situação',[['','Todas'],'Operando','Parado','Alerta','Offline','Manutenção'],filters.status)}${filterField('type','Categoria',[['','Todas'],'Trator','Colheitadeira','Pulverizador','Veículo de apoio'],filters.type)}</div><section class="panel">${assetTable(list)}</section>`;}
  function machineIllustration(type){if(type==='Veículo de apoio')return `<svg viewBox="0 0 420 200" role="img" aria-label="Ilustração de veículo de apoio"><ellipse cx="220" cy="166" rx="155" ry="9" fill="#c7d2bb"/><path d="M65 95h66l29-35h108l35 42 59 8v43H65z" fill="#e7e5db" stroke="#627859" stroke-width="3"/><path d="m172 69-25 30h68V69z M225 69v30h62l-26-30z" fill="#688477"/><circle cx="119" cy="152" r="28" fill="#314038"/><circle cx="307" cy="152" r="28" fill="#314038"/><circle cx="119" cy="152" r="14" fill="#aab5a1"/><circle cx="307" cy="152" r="14" fill="#aab5a1"/></svg>`;return `<svg viewBox="0 0 440 220" role="img" aria-label="Ilustração de máquina agrícola"><ellipse cx="218" cy="194" rx="175" ry="9" fill="#c7d2bb"/><path d="M52 120h117V56h116v69h78v43H52z" fill="#427448"/><path d="M184 66h89v66h-89z" fill="#8eb0a1"/><path d="M230 66v65 M180 61l103 0" fill="none" stroke="#294f3a" stroke-width="7"/><rect x="70" y="103" width="90" height="26" rx="6" fill="#609053"/><rect x="87" y="87" width="8" height="25" fill="#465d42"/><path d="M58 125h103 M59 131h103" stroke="#aac180" stroke-width="3"/><path d="M298 125h50v7h-50" fill="#a2b95f"/><circle cx="249" cy="163" r="45" fill="#26382e"/><circle cx="249" cy="163" r="28" fill="#cab55d"/><circle cx="249" cy="163" r="10" fill="#9f8d41"/><circle cx="89" cy="169" r="30" fill="#26382e"/><circle cx="89" cy="169" r="18" fill="#cab55d"/><path d="M183 139h24v30h-24z" fill="#284f34"/><path d="M365 153h28v9h-28" fill="#537249"/></svg>`;}
  function assetDetail(){const a=getAsset(selected),o=s.operators.find(o=>o.id===a.operator),result=M.authorize(s,a,o,s.clock);const events=visibleAudit().filter(e=>e.asset===a.id).slice(0,12);return head(`${a.id} · ${esc(a.name)}`,`${esc(a.type)} · Identificação ${a.plate}`,button('Voltar à frota','open-assets')+(isManager()?button(icon('settings',15)+' Regras do ativo','asset-rules',`data-id="${a.id}"`)+button(icon('rfid',15)+' Simular RFID','rfid',`data-id="${a.id}"`,'primary'):''))+`<div class="asset-detail-grid"><section class="panel"><div class="asset-hero">${machineIllustration(a.type)}</div><div class="asset-info"><div class="actions">${badge(a.status)}${badge(a.risk)}${badge(a.connection)}</div><div class="data-grid">${datum('Operador atual',opName(a.operator))}${datum('RFID',a.lastRfid||o?.rfid||'Não identificado')}${datum('Localização',areaName(a.area))}${datum('Velocidade',a.connection==='Offline'?'Último dado · '+a.speed+' km/h':a.speed+' km/h')}${datum('Ignição',a.ignition?'Ligada':'Desligada')}${datum('Alimentação',a.power)}${datum('Bateria do rastreador',a.battery+'%')}${datum('Última comunicação',s.date+' · '+a.updated)}${datum('Horário do ativo',a.start+' às '+a.end)}${datum('Geofence',a.allowedAreas.includes(a.area)?'Dentro da área permitida':'Fora da área permitida')}</div><div class="notice ${result.type==='irregular'?'red':''}"><b>Verificação das regras</b><br>${esc(result.reason)}${!a.operator?'<br>Ativo estacionado pode permanecer sem operador. RFID é exigido ao iniciar o uso.':''}</div>${a.connection==='LoRaWAN'?'<div class="callout">Celular indisponível. Comunicação de contingência ativa via LoRaWAN.</div>':''}${a.power==='Bateria interna'?'<div class="notice red" style="margin-top:12px">Alimentação principal interrompida. Bateria interna ativa após evento de violação.</div>':''}</div></section><section class="panel"><div class="panel-head"><div><h2>Timeline do ativo</h2><p>Identidade, autorização e sequência operacional</p></div>${icon('clock',18)}</div><div class="timeline">${events.map(e=>timelineItem(e.time,e.text,e.category+' · '+e.priority,e.priority==='Crítica')).join('')||'<div class="empty">Ativo cadastrado e monitorado. As próximas ações aparecerão aqui.</div>'}</div></section></div>`;}
  const timelineItem=(time,text,sub='',critical=false)=>`<div class="timeline-item ${critical?'critical':''}"><time>${esc(time)}</time><i class="t-dot"></i><div>${esc(text)}${sub?'<small>'+esc(sub)+'</small>':''}</div></div>`;
  function operatorsPage(){return head('Operadores','Identificação por RFID, vínculo às máquinas e horários permitidos.',button(icon('plus',15)+' Novo operador','operator-new')+button(icon('rfid',15)+' Simular leitura RFID','rfid','','primary'))+`<div class="cards">${s.operators.map(o=>`<section class="panel operator-card"><div class="operator-top"><span class="avatar">${initials(o.name)}</span><div><h3>${esc(o.name)}</h3><small>${o.id}</small></div></div>${badge(o.status)}<div class="data-grid">${datum('Crachá RFID',o.rfid)}${datum('Horário permitido',o.start+' – '+o.end)}</div><small>Ativos autorizados</small><p>${o.assets.join(' · ')||'Sem vínculos cadastrados'}</p><div class="actions">${button('Editar vínculos','operator-edit',`data-id="${o.id}"`,'small')}${button(o.status==='Ativo'?'Suspender':'Ativar','operator-toggle',`data-id="${o.id}"`,'small')}</div></section>`).join('')}</div>`;}
  function alertsPage(){const list=visibleAlerts().filter(a=>(!filters.priority||a.priority===filters.priority)&&(!filters.alertstatus||a.status===filters.alertstatus)&&(!filters.asset||a.asset===filters.asset));return head('Central de alertas','Cada alerta reúne ativo, operador, local, motivo e prioridade.')+`<div class="filters">${filterField('priority','Prioridade',[['','Todas'],'Crítica','Alta','Média','Baixa'],filters.priority)}${filterField('alertstatus','Status',[['','Todos'],'Aberto','Em análise','Resolvido'],filters.alertstatus)}${filterField('asset','Ativo',[['','Todos'],...visibleAssets().map(a=>[a.id,a.id+' · '+a.name])],filters.asset)}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Alerta / contexto</th><th>Ativo e operador</th><th>Prioridade</th><th>Horário e local</th><th>Status</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td class="text-wrap"><b>${esc(a.title)}</b><span class="sub">${esc(a.reason)}</span></td><td>${a.asset}<span class="sub">${esc(opName(a.operator))}</span></td><td>${badge(a.priority)}</td><td>${a.time}<span class="sub">${esc(areaName(a.area))}</span></td><td>${badge(a.status,a.status==='Em análise'?'orange':a.status==='Resolvido'?'':'red')}</td><td>${button('Analisar','alert-detail',`data-id="${a.id}"`,'small')}</td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">Nenhum alerta corresponde aos filtros.</div>':''}</div></section>`;}
  function occurrencesPage(){return head('Ocorrências','Dossiês com a sequência de eventos e a análise do gestor.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Dossiê</th><th>Ativo</th><th>Contexto</th><th>Prioridade</th><th>Status</th><th></th></tr></thead><tbody>${s.occurrences.map(o=>`<tr><td><b>${o.id}</b><span class="sub">${o.start}</span></td><td>${o.asset}<span class="sub">${esc(opName(o.operator))}</span></td><td class="text-wrap">${esc(o.reason)}<span class="sub">${o.events.length} eventos correlacionados</span></td><td>${badge(o.priority)}</td><td>${badge(o.status,o.status==='Aberta'?'red':'gray')}</td><td>${button('Abrir dossiê','dossier',`data-id="${o.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section>`;}
  let dossierId=null;
  try{const view=JSON.parse(sessionStorage.getItem(KEY+'-view'));if(view){selected=view.selected||selected;dossierId=view.dossierId||null;}}catch{}
  function dossier(){const o=s.occurrences.find(o=>o.id===dossierId)||s.occurrences[0],a=M.asset(s,o.asset);return head('Dossiê da ocorrência','Registro contextualizado para análise e resposta do responsável.',button('Voltar','open-occurrences')+button(icon('download',14)+' Exportar dossiê','export-dossier',`data-id="${o.id}"`)+button(icon('printer',14)+' Imprimir / PDF','print','','primary'))+`<article class="panel print-sheet"><div class="dossier-header"><div>${brand()}<h1>${o.id}</h1><p class="muted" style="font-size:12px">${esc(s.settings.farm)} · Protótipo acadêmico · Dados simulados</p></div><div>${badge(o.priority)} ${badge(o.status,o.status==='Aberta'?'red':'gray')}<p style="font-size:12px;margin-top:14px">Início: ${o.start}</p></div></div><div class="dossier-body"><div><h2>Contexto da ocorrência</h2><div class="data-grid">${datum('Ativo',a.id+' · '+a.name)}${datum('Categoria',a.type)}${datum('Operador no início',opName(o.operator))}${datum('Local da ocorrência',o.area)}${datum('Quantidade de eventos',o.events.length)}${datum('Prioridade',o.priority)}</div><div class="notice red"><b>Motivo</b><br>${esc(o.reason)}</div><div style="margin-top:23px"><h3>Análise do responsável</h3><p style="font-size:12px;line-height:1.9;margin-top:12px">${o.resolution?esc(o.resolution):'Ocorrência em acompanhamento. Verificar os eventos e registrar a decisão antes de encerrar.'}</p>${o.closedBy?'<small>Responsável: '+esc(o.closedBy)+' · '+(o.closedAt||'29/09/2026 23:10')+'</small>':button('Registrar análise e encerrar','occurrence-close',`data-id="${o.id}"`,'primary')}</div><div class="callout">O dossiê registra o que foi detectado e a decisão do gestor. A simulação não aciona equipes externas nem executa comandos em máquinas.</div></div><div><h2 style="margin-bottom:8px">Sequência dos acontecimentos</h2><div class="timeline">${o.events.map(e=>timelineItem(e.time,e.text)).join('')}</div></div></div></article>`;}
  function requestsPage(){return head('Autorizações','Regras por operador e decisões excepcionais registradas pelo gestor.',button(icon('rfid',15)+' Testar identificação','rfid','','primary'))+`<section class="panel"><div class="panel-head"><div><h2>Liberações excepcionais</h2><p>Uma decisão sempre registra responsável e justificativa</p></div>${badge(s.requests.filter(r=>r.status==='Pendente').length+' pendente(s)','orange')}</div>${s.requests.map(r=>`<div class="request"><div>${badge(r.status)} <small>${r.id} · ${r.time}</small><h3>${esc(opName(r.operator))} · ${r.asset}</h3><p>${esc(r.reason)}${r.justification?'<br><b>'+esc(r.manager)+'</b>: '+esc(r.justification):''}${r.validUntil?'<br>Liberação excepcional válida na simulação até 23:59 de 30/09/2026.':''}</p></div><div class="actions">${r.status==='Pendente'?button('Negar uso','request-decision',`data-id="${r.id}" data-approved="false"`,'danger')+button('Autorizar uso','request-decision',`data-id="${r.id}" data-approved="true"`,'primary'):badge('Decisão auditada','gray')}</div></div>`).join('')||'<div class="empty">Sem solicitações pendentes.<br>Use “Simular incidente → Uso fora do horário” para demonstrar a decisão do gestor.</div>'}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Regras operacionais por ativo</h2></div><div class="table-wrap"><table><thead><tr><th>Ativo</th><th>Operadores autorizados</th><th>Horário</th><th>Áreas</th><th></th></tr></thead><tbody>${s.assets.map(a=>`<tr><td>${a.id}</td><td class="text-wrap">${s.operators.filter(o=>o.assets.includes(a.id)&&o.status==='Ativo').map(o=>esc(o.name)).join(', ')||'Nenhum operador ativo'}</td><td>${a.start} – ${a.end}</td><td>${a.allowedAreas.length} áreas</td><td>${button('Editar regras','asset-rules',`data-id="${a.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section>`;}
  function areasPage(){return head('Áreas permitidas','Cercas virtuais esquemáticas para delimitar o uso autorizado.')+`<section class="panel" style="margin-bottom:20px">${farmMap()}${legend()}</section><div class="cards">${s.areas.map(z=>`<section class="panel area-card"><div class="actions" style="justify-content:space-between"><h3>${esc(z.name)}</h3>${badge('Geofence ativa')}</div><div class="area-swatch" style="background-color:${z.color}"></div><p>${s.assets.filter(a=>a.area===z.id).length} ativos nesta área<br>${s.assets.filter(a=>a.allowedAreas.includes(z.id)).length} ativos com permissão de acesso</p><div class="actions">${button('Editar área','area-edit',`data-id="${z.id}"`,'small')}${button('Ver no mapa','open-map','','link small')}</div></section>`).join('')}</div><div class="notice" style="margin-top:20px">As áreas são fictícias. As permissões de acesso são configuradas nas regras de cada ativo. A simulação de saída de geofence posiciona a máquina fora do perímetro.</div>`;}
  function historyPage(){const list=visibleAudit().filter(e=>(!filters.asset||e.asset===filters.asset)&&(!filters.operator||e.operator===filters.operator)&&(!filters.category||e.category===filters.category)&&(!filters.priority||e.priority===filters.priority)&&(!filters.from||e.date>=filters.from)&&(!filters.to||e.date<=filters.to));return head('Histórico e auditoria','Ações importantes, eventos e decisões preservados na demonstração.',button(icon('download',14)+' Exportar histórico','export-audit'))+`<div class="filters">${filterField('asset','Ativo',[['','Todos'],...visibleAssets().map(a=>a.id)],filters.asset)}${filterField('operator','Operador',[['','Todos'],...(isManager()?s.operators:s.operators.filter(o=>o.id===session.operator)).map(o=>[o.id,o.name])],filters.operator)}${filterField('category','Categoria',[['','Todas'],...new Set(visibleAudit().map(e=>e.category))],filters.category)}${filterField('priority','Gravidade',[['','Todas'],'Baixa','Média','Alta','Crítica'],filters.priority)}<div class="field"><label for="from">De</label><input type="date" id="from" data-filter="from" value="${esc(filters.from||'')}"></div><div class="field"><label for="to">Até</label><input type="date" id="to" data-filter="to" value="${esc(filters.to||'')}"></div></div><section class="panel"><div class="panel-head"><h2>${list.length} registros</h2>${button('Limpar filtros','clear-filters','','link small')}</div><div class="table-wrap"><table><thead><tr><th>Data / horário</th><th>Ativo</th><th>Operador</th><th>Categoria</th><th>Gravidade</th><th>Evento</th></tr></thead><tbody>${list.map(e=>`<tr><td>${e.time}<span class="sub">${e.date}</span></td><td>${esc(e.asset||'Central')}</td><td>${esc(opName(e.operator))}</td><td>${esc(e.category)}</td><td>${badge(e.priority)}</td><td class="text-wrap">${esc(e.text)}</td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">Nenhum evento corresponde ao período e aos filtros.</div>':''}</div></section>`;}
  function settingsPage(){return head('Configurações','Preferências da central e limites do ambiente demonstrativo.')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>${isManager()?'Preferências da propriedade':'Seu acesso'}</h2></div>${isManager()?`<form id="settings-form" class="settings-form"><div class="field"><label for="farm-name">Nome da propriedade</label><input id="farm-name" maxlength="60" required value="${esc(s.settings.farm)}"></div><div class="field"><label for="manager-name">Gestor responsável</label><input id="manager-name" maxlength="50" required value="${esc(s.settings.manager)}"></div><div class="field"><label for="retention">Retenção demonstrativa no navegador</label><select id="retention">${[30,90,180].map(n=>`<option ${n===s.settings.retention?'selected':''} value="${n}">${n} dias</option>`).join('')}</select><small>Política representada na interface; a limpeza é manual neste protótipo.</small></div><div class="check-list"><label><input type="checkbox" id="notify" ${s.settings.notifications?'checked':''}> Exibir avisos de simulação</label></div><button type="submit" class="btn primary">Salvar preferências</button></form>`:`<div class="panel-body"><p style="line-height:1.9">${esc(session.name)} · Operador<br>Acesso restrito aos ativos vinculados ao seu crachá.</p></div>`}</section><section class="panel"><div class="panel-head"><h2>Privacidade e controle de acesso</h2></div><div class="panel-body"><div class="permission-row"><b>Gestor</b><br>Visão da frota, operadores, alertas e decisões de liberação.</div><div class="permission-row"><b>Operador</b><br>Consulta dos ativos vinculados e do histórico da sua operação.</div><div class="permission-row"><b>Dados mínimos</b><br>Nome fictício, código do crachá e vínculos operacionais. Sem CPF, telefone ou dados reais.</div><div class="notice" style="margin-top:20px">Autenticação e permissões são demonstrativas no navegador. Esta versão não oferece segurança de produção nem comprova conformidade legal.</div></div></section></div>${isManager()?`<section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Preparação da apresentação</h2><p>Recomece a demonstração ou salve os dados desta sessão</p></div></div><div class="panel-body"><div class="actions">${button(icon('refresh',14)+' Restaurar dados de demonstração','reset-prompt')}${button(icon('download',14)+' Backup completo','backup')}${button('Recuperar sessão anterior','restore-prompt')}</div><p style="margin-top:15px;font-size:11px;color:var(--muted);line-height:1.8">A restauração cria uma cópia da sessão atual antes de repor os dados fictícios. O cenário principal pode ser demonstrado novamente.</p></div></section>`:''}`;}
  function scenarioBanner(){if(!isManager()||!s.scenario)return '';const sc=s.scenario;return `<div class="demo-banner"><div><b>${sc.done?'Demonstração concluída':'Demonstração em andamento'} · ${sc.asset}</b><p>${sc.done?'4 etapas correlacionadas em um dossiê.':'Etapa '+sc.step+' de 4 · avance para acompanhar a ocorrência.'}</p></div><div class="actions">${!sc.done?button('Continuar cenário '+icon('arrow',14),'scenario-view','','primary'):button('Abrir dossiê '+icon('folder',14),'dossier',`data-id="${sc.occurrence}"`,'primary')}${button('Fechar faixa','scenario-hide','','small')}</div></div>`;}
  function showModal(title,body,footer='',large=false){modalFocus=document.activeElement;$('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar janela">${icon('close',16)}</button></header><div class="modal-body">${body}</div>${footer?'<footer class="modal-footer">'+footer+'</footer>':''}</section></div>`;document.body.style.overflow='hidden';$('modal-root').querySelector('input:not([type="hidden"]),select,button')?.focus();}
  function closeModal(){if(timer){clearInterval(timer);timer=null;}$('modal-root').innerHTML='';document.body.style.overflow='';modalFocus?.focus?.();}
  const assetSelect=(id='modal-asset',selectedId=selected)=>`<div class="field"><label for="${id}">Ativo</label><select id="${id}">${visibleAssets().map(a=>`<option value="${a.id}" ${a.id===selectedId?'selected':''}>${a.id} · ${esc(a.name)}</option>`).join('')}</select></div>`;
  function rfidModal(id=selected){showModal('Simular leitura RFID',`<p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:20px">Identifique o crachá e verifique operador, horário e área do ativo.</p><div class="form-grid">${assetSelect('rfid-asset',id)}<div class="field"><label for="rfid-operator">Crachá / operador</label><select id="rfid-operator">${s.operators.map(o=>`<option value="${o.id}">${esc(o.name)} · ${o.rfid}${o.status==='Suspenso'?' · Suspenso':''}</option>`).join('')}</select></div><div class="field"><label for="rfid-time">Horário da leitura</label><input type="time" id="rfid-time" value="14:32" required></div><div class="notice">Horário padrão: 06h às 18h.<br>Selecione outro crachá para testar uso irregular.</div></div><div id="rfid-result" role="status"></div>`,button('Fechar','close-modal')+button(icon('rfid',16)+' Ler crachá','rfid-read','','primary'));}
  const scenarios=[['normal','check','Uso normal','RFID, horário e área aprovados'],['unauthorized','users','Operador não autorizado','Crachá sem vínculo com o ativo'],['geofence','pin','Saída de área permitida','Alerta crítico e novo dossiê'],['afterhours','clock','Uso fora do horário','Gestor autoriza ou nega a exceção'],['cellular','signal','Perda de sinal celular','Contingência por LoRaWAN'],['tamper','shield','Tentativa de violação','Bateria interna e dossiê'],['offline','alert','Rastreador desconectado','Última posição conhecida'],['battery','battery','Bateria crítica','Nível de carga abaixo de 10%']];
  function simulationModal(){showModal('Simular incidente',`${assetSelect()}<div class="scenario-console" style="margin-top:20px"><span class="eyebrow">DEMONSTRAÇÃO PRINCIPAL</span><h3>Movimentação suspeita às 22h43</h3><p>RFID ausente → saída da geofence → perda celular → violação. Quatro etapas e um dossiê.</p><div style="margin-top:15px">${button('Iniciar cenário completo '+icon('play',14),'scenario-start','','primary')}</div></div><div class="scenario-grid">${scenarios.map(([id,ic,name,note])=>`<button class="scenario-btn" data-action="simulate-one" data-kind="${id}">${icon(ic,19)}<div><b>${name}</b><small>${note}</small></div></button>`).join('')}</div>`);}
  function scenarioModal(){const sc=s.scenario;if(!sc)return;showModal('Demonstração principal',`<div class="scenario-console"><span class="eyebrow">${sc.asset} · ${s.clock} · TEMPO SIMULADO</span><h3>${sc.done?'Dossiê completo gerado':'Acompanhe a sequência dos eventos'}</h3><p>${sc.done?'A ocorrência reúne identidade, horário, geofence, conectividade e violação.':'O ativo deveria estar estacionado. Avance as etapas ou reproduza automaticamente.'}</p><div class="scenario-steps">${['22:43 · Uso irregular','22:44 · Geofence','22:45 · LoRaWAN','22:46 · Violação'].map((v,i)=>`<div class="scenario-step ${sc.step>i?'done':''}">${sc.step>i?'✓ ':''}${v}</div>`).join('')}</div></div><div style="margin-top:12px">${sc.events.map(e=>timelineItem(e.time,e.text)).join('')||'<div class="empty">Pronto para iniciar · trator estacionado no galpão.</div>'}</div>`,sc.done?button('Ver monitoramento','scenario-to-map')+button('Abrir dossiê '+icon('folder',14),'scenario-to-dossier','','primary'):button('Pausar / fechar','close-modal')+button(timer?'Reproduzindo…':'Reproduzir automaticamente','scenario-auto',timer?'disabled':'')+button('Próxima etapa '+icon('arrow',14),'scenario-next',timer?'disabled':'','primary'),true);}
  function alertModal(id){const al=s.alerts.find(a=>a.id===id);if(!al||!canView(al.asset))throw Error('Alerta não encontrado.');showModal(al.title,`<div class="actions">${badge(al.priority)}${badge(al.status,'gray')}<small>${al.id}</small></div><div class="data-grid">${datum('Ativo',al.asset+' · '+M.asset(s,al.asset).name)}${datum('Operador',opName(al.operator))}${datum('Horário',al.date+' '+al.time)}${datum('Local',areaName(al.area))}</div><div class="notice ${al.priority==='Crítica'?'red':''}">${esc(al.reason)}</div><p style="margin-top:20px;color:var(--muted);font-size:12px;line-height:1.8">Analise os eventos e registre o acompanhamento. ${al.occurrence?'Este alerta pertence ao dossiê '+al.occurrence+'.':'Pode ser resolvido após a verificação do responsável.'}</p>`,button('Fechar','close-modal')+(al.status==='Aberto'?button('Assumir análise','alert-assume',`data-id="${id}"`):'')+(al.occurrence?button('Abrir dossiê','dossier',`data-id="${al.occurrence}"`,'primary'):al.status!=='Resolvido'?button('Registrar resolução','alert-resolve',`data-id="${id}"`,'primary'):''));}
  function justificationModal(title,action,id,approved){showModal(title,`<div class="field"><label for="justification">${action==='decision-submit'?'Justificativa da decisão':'Análise e ação realizada'}</label><textarea id="justification" maxlength="600" placeholder="Registre o motivo e a ação do responsável."></textarea></div><p class="muted" style="font-size:11px;line-height:1.8;margin-top:15px">Responsável: ${esc(s.settings.manager)} · Horário simulado: ${s.clock}. Esta ação será registrada na auditoria.</p><div id="modal-error" class="error" role="alert"></div>`,button('Cancelar','close-modal')+button('Confirmar registro',action,`data-id="${id}" ${approved!=null?'data-approved="'+approved+'"':''}`,'primary'));}
  function operatorModal(id){const o=id?s.operators.find(o=>o.id===id):{name:'',rfid:'',assets:[],start:'06:00',end:'18:00',status:'Ativo'};showModal(id?'Editar operador':'Novo operador',`<form id="operator-form" data-id="${id||''}"><div class="form-grid"><div class="field"><label for="op-name">Nome do operador</label><input id="op-name" required maxlength="60" value="${esc(o.name)}"></div><div class="field"><label for="op-rfid">Código RFID</label><input id="op-rfid" required maxlength="20" value="${esc(o.rfid)}" pattern="[A-Za-z0-9-]+"></div><div class="field"><label for="op-start">Início do horário</label><input id="op-start" type="time" value="${o.start}" required></div><div class="field"><label for="op-end">Fim do horário</label><input id="op-end" type="time" value="${o.end}" required></div><div class="wide"><small>Ativos autorizados</small><div class="check-list">${s.assets.map(a=>`<label><input type="checkbox" name="op-assets" value="${a.id}" ${o.assets.includes(a.id)?'checked':''}> ${a.id}</label>`).join('')}</div></div></div><div id="modal-error" class="error" role="alert"></div><button class="btn primary" type="submit">Salvar operador e vínculos</button></form>`);}
  function rulesModal(id){const a=M.asset(s,id);showModal('Regras de operação · '+id,`<form id="rules-form" data-id="${id}"><div class="form-grid"><div class="field"><label for="rule-start">Horário inicial</label><input id="rule-start" type="time" required value="${a.start}"></div><div class="field"><label for="rule-end">Horário final</label><input id="rule-end" type="time" required value="${a.end}"></div><div class="wide"><small>Áreas permitidas</small><div class="check-list">${s.areas.map(z=>`<label><input type="checkbox" name="rule-areas" value="${z.id}" ${a.allowedAreas.includes(z.id)?'checked':''}>${esc(z.name)}</label>`).join('')}</div></div></div><div class="notice" style="margin:20px 0">O horário do operador também é verificado. Exceções de horário são decididas pelo gestor na tela Autorizações.</div><div id="modal-error" class="error" role="alert"></div><button type="submit" class="btn primary">Salvar regras</button></form>`);}
  function areaModal(id){const z=s.areas.find(z=>z.id===id);showModal('Editar área permitida',`<form id="area-form" data-id="${id}"><div class="field"><label for="area-name">Nome da área</label><input id="area-name" required maxlength="40" value="${esc(z.name)}"></div><div class="form-grid" style="margin-top:20px">${[['x','Posição horizontal (%)',0,95],['y','Posição vertical (%)',0,95],['w','Largura (%)',3,90],['h','Altura (%)',3,90]].map(([key,label,min,max])=>`<div class="field"><label for="area-${key}">${label}</label><input id="area-${key}" type="number" min="${min}" max="${max}" required value="${z[key]}"></div>`).join('')}</div><div id="modal-error" class="error" role="alert"></div><button type="submit" class="btn primary" style="margin-top:20px">Salvar área</button></form>`);}
  function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo preparado: '+name);}
  function csv(rows){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,'\t$&').replace(/"/g,'""')+'"';return '\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\r\n');}
  const slides=[
    {kicker:'SEGURANÇA E RASTREAMENTO NO AGRONEGÓCIO',title:'Vigia Rural',text:'Segurança, rastreamento e inteligência para ativos agrícolas de alto valor.',list:['Projeto acadêmico · Arthur e Andrei','Protótipo funcional com dados e sensores simulados']},
    {kicker:'O PROBLEMA',title:'Vulnerabilidade no campo',text:'Propriedades extensas e cobertura de rede limitada dificultam o acompanhamento das máquinas.',list:['Movimentação suspeita percebida tarde','Operador e autorização sem registro integrado','Pouco contexto para decidir como responder']},
    {kicker:'PROPOSTA DE VALOR',title:'Um alerta sem contexto não resolve o problema',text:'A central relaciona a localização com o operador, a autorização, o horário e a área permitida.',list:['Qual máquina? Onde está?','Quem está usando? O uso foi autorizado?','O que aconteceu e qual decisão foi registrada?']},
    {kicker:'OPERAÇÃO',title:'Identificar, verificar e monitorar',text:'A leitura RFID vincula o operador à máquina. As regras classificam o uso antes de registrar a operação.',list:['Uso normal → registrar no histórico','Uso irregular → alertar o gestor','Exceção de horário → solicitar liberação']},
    {kicker:'INFRAESTRUTURA REPRESENTADA',title:'Comunicação e proteção do rastreador',text:'O protótipo demonstra as mudanças de estado de uma infraestrutura embarcada.',list:['GPS + celular: posição e comunicação principal','LoRaWAN: contingência com gateway local','Anti-violação: corte de alimentação e bateria interna']},
    {kicker:'DEMONSTRAÇÃO AO VIVO',title:'Uma ocorrência em quatro etapas',text:'Um trator que deveria estar estacionado começa a se mover à noite.',list:['22:43 · Sem RFID válido e fora do horário','22:44 · Saída da área permitida','22:45 · Contingência LoRaWAN','22:46 · Violação e dossiê completo']},
    {kicker:'MODELO DE NEGÓCIO PROPOSTO',title:'Monetização B2B',text:'Modelo conceitual a validar com produtores e parceiros.',list:['Assinatura mensal por ativo monitorado','Venda ou locação de rastreadores e instalação','Parcerias com cooperativas e seguradoras']},
    {kicker:'PRIVACIDADE E PRÓXIMOS PASSOS',title:'Resposta organizada, com histórico',text:'O MVP demonstra a experiência de gestão do risco. A operação real exige validação em campo e integração com hardware.',list:['Dados mínimos e visualização por perfil','Decisões do gestor registradas na auditoria','Próxima etapa: testar cobertura, sensores e regras numa propriedade']}
  ];
  function presentation(){const sl=slides[slideIndex];let el=$('presentation');if(!el){el=document.createElement('section');el.id='presentation';document.body.append(el);}el.className='presentation';el.setAttribute('aria-label','Apresentação do projeto Vigia Rural');el.innerHTML=`<div class="presentation-top">${brand()}${button('Fechar '+icon('close',15),'presentation-close','','small')}</div><div class="slide"><span class="eyebrow" style="color:#96b478">${sl.kicker}</span><h1>${sl.title}</h1><p>${sl.text}</p><div class="slide-list">${sl.list.map((t,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span>${t}</div>`).join('')}</div></div><div class="presentation-footer"><span>VIGIA RURAL · ${slideIndex+1} / ${slides.length} · ← → para navegar</span><div class="actions">${button('Anterior','slide-prev',slideIndex===0?'disabled':'','small')}${slideIndex===5&&session?button('Abrir demonstração','slide-demo','','primary'):''}${button(slideIndex===slides.length-1?'Encerrar':'Próximo '+icon('arrow',14),slideIndex===slides.length-1?'presentation-close':'slide-next','','small')}</div></div><div class="progress"><i style="width:${(slideIndex+1)/slides.length*100}%"></i></div>`;}
  function closePresentation(){ $('presentation')?.remove(); }
  async function handle(action,el){const id=el?.dataset.id;
    switch(action){
      case 'menu':$('sidebar').classList.toggle('open');break;
      case 'login-profile':document.querySelectorAll('.login-switch button').forEach(b=>b.classList.toggle('selected',b===el));$('login-role').value=el.dataset.role;$('email').value=el.dataset.role==='Gestor'?'admin@vigiarural.com':'operador@vigiarural.com';$('password').value=el.dataset.role==='Gestor'?'admin123':'operador123';break;
      case 'logout':closeModal();session=null;try{sessionStorage.removeItem(SESSION);}catch{}page='dashboard';render();break;
      case 'open-map':nav('mapa');break;case 'open-assets':nav('ativos');break;case 'open-alerts':nav('alertas');break;case 'open-occurrences':nav('ocorrencias');break;
      case 'asset-detail':getAsset(id);selected=id;nav('detalhe');break;
      case 'map-asset':getAsset(id);selected=id;if(page!=='mapa')nav('mapa');else render();break;
      case 'map-select':showModal('Selecionar ativo',assetSelect(),button('Exibir no mapa','map-show','','primary'));break;
      case 'map-show':selected=$('modal-asset').value;closeModal();render();break;
      case 'simulate':checkedManager();simulationModal();break;
      case 'simulate-one':{checkedManager();const id=$('modal-asset').value,result=M.simulate(s,el.dataset.kind,id);selected=id;save();closeModal();render();if(s.settings.notifications)toast(result.title+' · '+result.reason);break;}
      case 'scenario-start':checkedManager();M.startScenario(s,$('modal-asset').value);selected=s.scenario.asset;save();render();scenarioModal();break;
      case 'scenario-view':scenarioModal();break;
      case 'scenario-next':checkedManager();M.advanceScenario(s);save();render();scenarioModal();break;
      case 'scenario-auto':checkedManager();if(timer)return;timer=setInterval(()=>{M.advanceScenario(s);save();render();if(s.scenario.done){clearInterval(timer);timer=null;}scenarioModal();},2400);el.disabled=true;el.textContent='Reproduzindo…';break;
      case 'scenario-hide':if(s.scenario&&!s.scenario.done){toast('Conclua as quatro etapas antes de fechar a faixa.');break;}s.scenario=null;save();render();break;
      case 'scenario-to-map':closeModal();nav('mapa');break;
      case 'scenario-to-dossier':dossierId=s.scenario.occurrence;nav('dossie');break;
      case 'rfid':checkedManager();rfidModal(id||selected);break;
      case 'rfid-read':{checkedManager();const time=$('rfid-time').value;if(!time)throw Error('Selecione o horário da leitura.');const id=$('rfid-asset').value,op=$('rfid-operator').value,res=M.readRfid(s,id,op,time+':00');save();render();$('rfid-result').innerHTML=`<div class="rfid-result ${res.type}"><span class="eyebrow">OPERADOR IDENTIFICADO</span><h3>${esc(opName(op))}</h3><p>RFID: ${esc(M.operator(s,op).rfid)} · ${id} · ${time}</p><h3>${res.title}</h3><p>${esc(res.reason)}</p>${res.type==='exception'?button('Analisar solicitação','open-requests','','primary small'):''}</div>`;break;}
      case 'open-requests':nav('autorizacoes');break;
      case 'request-decision':checkedManager();justificationModal(el.dataset.approved==='true'?'Autorizar uso excepcional':'Negar uso excepcional','decision-submit',id,el.dataset.approved);break;
      case 'decision-submit':{checkedManager();M.decide(s,id,el.dataset.approved==='true',$('justification').value,session.role);save();closeModal();render();toast('Decisão registrada no histórico.');break;}
      case 'alert-detail':alertModal(id);break;
      case 'alert-assume':{checkedManager();const al=s.alerts.find(a=>a.id===id);al.status='Em análise';M.log(s,s.clock,al.asset,al.operator,'Alerta',al.priority,`${s.settings.manager} assumiu a análise de ${al.id}.`);save();render();alertModal(id);break;}
      case 'alert-resolve':checkedManager();justificationModal('Resolver alerta','alert-resolve-submit',id);break;
      case 'alert-resolve-submit':{checkedManager();const text=$('justification').value.trim();if(!text)throw Error('Registre a análise do responsável.');const al=s.alerts.find(a=>a.id===id);al.status='Resolvido';al.resolution=text;M.log(s,s.clock,al.asset,al.operator,'Alerta','Baixa',`${s.settings.manager} resolveu ${id}: ${text}`);save();closeModal();render();toast('Resolução registrada. O estado físico do ativo permanece disponível para análise.');break;}
      case 'dossier':checkedManager();dossierId=id;nav('dossie');break;
      case 'occurrence-close':checkedManager();if(s.scenario?.occurrence===id&&!s.scenario.done)throw Error('Conclua as quatro etapas antes de encerrar a ocorrência.');justificationModal('Registrar análise e encerrar','occurrence-close-submit',id);break;
      case 'occurrence-close-submit':checkedManager();M.closeOccurrence(s,id,$('justification').value,session.role);save();closeModal();render();toast('Ocorrência encerrada e decisão auditada.');break;
      case 'export-dossier':checkedManager();download(id+'.json',JSON.stringify({project:'Vigia Rural',disclaimer:'Protótipo acadêmico · dados simulados',...s.occurrences.find(o=>o.id===id)},null,2));break;
      case 'print':window.print();break;
      case 'operator-new':checkedManager();operatorModal();break;
      case 'operator-edit':checkedManager();operatorModal(id);break;
      case 'operator-toggle':{checkedManager();const o=s.operators.find(o=>o.id===id);o.status=o.status==='Ativo'?'Suspenso':'Ativo';M.log(s,s.clock,null,id,'Cadastro','Média',`${s.settings.manager} alterou ${o.name} para ${o.status}.`);save();render();toast('Situação do operador atualizada. A próxima leitura RFID verificará esta regra.');break;}
      case 'asset-rules':checkedManager();rulesModal(id);break;
      case 'area-edit':checkedManager();areaModal(id);break;
      case 'export-assets':{const rows=[['Código','Modelo','Categoria','Operador','Status','Conexão','Bateria (%)','Local'],...visibleAssets().map(a=>[a.id,a.name,a.type,opName(a.operator),a.status,a.connection,a.battery,areaName(a.area)])];download('Vigia Rural - ativos.csv',csv(rows),'text/csv;charset=utf-8');break;}
      case 'export-audit':{const events=visibleAudit().filter(e=>(!filters.asset||e.asset===filters.asset)&&(!filters.operator||e.operator===filters.operator)&&(!filters.category||e.category===filters.category)&&(!filters.priority||e.priority===filters.priority)&&(!filters.from||e.date>=filters.from)&&(!filters.to||e.date<=filters.to));download('Vigia Rural - auditoria.csv',csv([['Data','Horário','Ativo','Operador','Categoria','Gravidade','Registro'],...events.map(e=>[e.date,e.time,e.asset,opName(e.operator),e.category,e.priority,e.text])]),'text/csv;charset=utf-8');break;}
      case 'clear-filters':filters={};render();break;
      case 'backup':checkedManager();download('Vigia Rural - backup.json',JSON.stringify(s,null,2));break;
      case 'reset-prompt':checkedManager();showModal('Preparar uma nova demonstração','<p style="font-size:13px;line-height:1.9">Os dados fictícios iniciais serão restaurados. A sessão atual será guardada no navegador para recuperação.</p>',button('Cancelar','close-modal')+button('Restaurar demonstração','reset-submit','','primary'));break;
      case 'reset-submit':checkedManager();try{localStorage.setItem(KEY+'-backup',JSON.stringify(s));}catch{}s=M.seed();selected='TR-001';save();closeModal();nav('dashboard');toast('Demonstração restaurada. Sessão anterior preservada.');break;
      case 'restore-prompt':checkedManager();showModal('Recuperar sessão anterior','<p style="font-size:13px;line-height:1.9">A cópia anterior à última restauração será recuperada. A sessão atual será preservada para permitir alternar entre as duas.</p>',button('Cancelar','close-modal')+button('Recuperar','restore-submit','','primary'));break;
      case 'restore-submit':{checkedManager();let previous;try{previous=JSON.parse(localStorage.getItem(KEY+'-backup'));}catch{}if(!previous||previous.version!==1)throw Error('Não existe sessão anterior para recuperar.');localStorage.setItem(KEY+'-backup',JSON.stringify(s));s=previous;save();closeModal();render();toast('Sessão anterior recuperada.');break;}
      case 'close-modal':closeModal();break;
      case 'presentation':slideIndex=0;presentation();break;
      case 'presentation-close':closePresentation();break;
      case 'slide-next':slideIndex=Math.min(slides.length-1,slideIndex+1);presentation();break;
      case 'slide-prev':slideIndex=Math.max(0,slideIndex-1);presentation();break;
      case 'slide-demo':closePresentation();simulationModal();break;
    }
  }
  document.addEventListener('click',e=>{const navEl=e.target.closest('[data-nav]');if(navEl){nav(navEl.dataset.nav);return;}const el=e.target.closest('[data-action]');if(el){Promise.resolve(handle(el.dataset.action,el)).catch(error=>{if($('modal-error'))$('modal-error').textContent=error.message;else toast(error.message);});}else if(e.target.classList.contains('modal-backdrop'))closeModal();});
  document.addEventListener('input',e=>{if(e.target.dataset.filter&&e.target.tagName==='INPUT'&&e.target.type!=='date'){filters[e.target.dataset.filter]=e.target.value;render();}});
  document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render();}});
  document.addEventListener('submit',e=>{e.preventDefault();try{
    if(e.target.id==='login-form'){
      const role=$('login-role').value,email=$('email').value.trim().toLowerCase(),password=$('password').value;
      if((role==='Gestor'&&(email!=='admin@vigiarural.com'||password!=='admin123'))||(role==='Operador'&&(email!=='operador@vigiarural.com'||password!=='operador123'))){$('login-error').textContent='Confira o e-mail e a senha da conta de demonstração.';return;}
      session={role,name:role==='Gestor'?s.settings.manager:'Carlos Mendes',operator:role==='Operador'?'OP-001':null};try{sessionStorage.setItem(SESSION,JSON.stringify(session));}catch{}M.log(s,s.clock,null,session.operator,'Acesso','Baixa',`${session.name} acessou a central como ${role}.`);save();page='dashboard';render();window.scrollTo(0,0);return;
    }
    checkedManager();
    if(e.target.id==='settings-form'){s.settings.farm=$('farm-name').value.trim();s.settings.manager=$('manager-name').value.trim();if(!s.settings.farm||!s.settings.manager)throw Error('Preencha propriedade e gestor.');s.settings.retention=Number($('retention').value);s.settings.notifications=$('notify').checked;session.name=s.settings.manager;try{sessionStorage.setItem(SESSION,JSON.stringify(session));}catch{}M.log(s,s.clock,null,null,'Configuração','Baixa','Preferências da propriedade atualizadas.');save();render();toast('Preferências salvas.');return;}
    if(e.target.id==='operator-form'){
      const id=e.target.dataset.id,name=$('op-name').value.trim(),rfid=$('op-rfid').value.trim().toUpperCase(),start=$('op-start').value,end=$('op-end').value;
      if(!name||!rfid||!start||!end)throw Error('Preencha nome, crachá e horários.');if(s.operators.some(o=>o.rfid===rfid&&o.id!==id))throw Error('Este crachá já pertence a outro operador.');
      const list=[...document.querySelectorAll('input[name="op-assets"]:checked')].map(el=>el.value);let o=s.operators.find(o=>o.id===id);if(!o){o={id:'OP-'+String(s.nextId++).padStart(3,'0'),status:'Ativo'};s.operators.push(o);}Object.assign(o,{name,rfid,start,end,assets:list});M.log(s,s.clock,null,o.id,'Cadastro','Baixa',`${s.settings.manager} salvou o operador ${name} e ${list.length} vínculos de ativos.`);
    }else if(e.target.id==='rules-form'){
      const a=M.asset(s,e.target.dataset.id),list=[...document.querySelectorAll('input[name="rule-areas"]:checked')].map(el=>el.value);if(!list.length)throw Error('Selecione ao menos uma área permitida.');a.start=$('rule-start').value;a.end=$('rule-end').value;a.allowedAreas=list;M.log(s,s.clock,a.id,null,'Autorização','Média',`${s.settings.manager} atualizou horários e geofences do ativo.`);
    }else if(e.target.id==='area-form'){
      const z=s.areas.find(z=>z.id===e.target.dataset.id),val={name:$('area-name').value.trim(),x:Number($('area-x').value),y:Number($('area-y').value),w:Number($('area-w').value),h:Number($('area-h').value)};if(!val.name||val.x+val.w>100||val.y+val.h>100)throw Error('A área deve ter nome e permanecer dentro dos limites do mapa (100%).');Object.assign(z,val);s.assets.forEach(a=>{const inside=a.x>=z.x&&a.x<=z.x+z.w&&a.y>=z.y&&a.y<=z.y+z.h;if(inside)a.area=z.id;else if(a.area===z.id)a.area=s.areas.find(other=>a.x>=other.x&&a.x<=other.x+other.w&&a.y>=other.y&&a.y<=other.y+other.h)?.id||'fora';});M.log(s,s.clock,null,null,'Geofence','Média',`${s.settings.manager} atualizou a área ${z.name}.`);
    }
    save();closeModal();render();toast('Alterações salvas e registradas na auditoria.');
  }catch(error){if($('modal-error'))$('modal-error').textContent=error.message;else toast(error.message);}});
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'){closeModal();closePresentation();$('sidebar')?.classList.remove('open');}
    if($('presentation')){if(e.key==='ArrowRight'){slideIndex=Math.min(slides.length-1,slideIndex+1);presentation();}if(e.key==='ArrowLeft'){slideIndex=Math.max(0,slideIndex-1);presentation();}}
    if(e.key==='Tab'&&$('modal-root').firstChild){const focusables=[...$('modal-root').querySelectorAll('button:not(:disabled),input:not([type="hidden"]),select,textarea,a')];const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}
  });
  window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(target){page=target;filters={};render();}});
  page=location.hash.slice(1)||'dashboard';render();
})();
